            case data = "data"
            case metadata = "metadata"
        }
    }

    /// `GET /nodes/{node}/vzdump/defaults`
    ///
    /// Get the currently configured vzdump defaults.
    public struct GetNodesVzdumpDefaults: PVEAPIRequest, Hashable {
        public typealias Response = Output
        public static let method: HTTPMethod = .get
        public static let pathTemplate = "/nodes/{node}/vzdump/defaults"
        public static let schemaName = "defaults"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// The storage identifier.
        ///
        /// Format: `pve-storage-id`.
        public var storage: String?

        public init(node: String) {
            self.node = node
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "vzdump", "defaults") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = storage { result.append(("storage", value.parameterValue)) }
            return result
        }

        public struct Output: Decodable, Sendable, Hashable {
            /// Backup all known guest systems on this host.
            public var all: Bool?
            /// Limit I/O bandwidth (in KiB/s).
            public var bwlimit: Int?
            /// Compress dump file.
            public var compress: String?
            /// Store resulting files to specified directory.
            public var dumpdir: String?
            /// Exclude specified guest systems (assumes --all)
            public var exclude: String?
            /// Exclude certain files/directories (shell globs). Paths starting with '/' are anchored to the container's root, other paths match relative to each subdirectory.
            public var excludePath: [String]?
            /// Options for backup fleecing (VM only).
            public var fleecing: String?
            /// Set IO priority when using the BFQ scheduler. For snapshot and suspend mode backups of VMs, this only affects the compressor. A value of 8 means the idle priority is used, otherwise the best-effort priority is used with the specified value.
            public var ionice: Int?
            /// Maximal time to wait for the global lock (minutes).
            public var lockwait: Int?
            /// Deprecated: use notification targets/matchers instead. Specify when to send a notification mail
            public var mailnotification: String?
            /// Deprecated: Use notification targets/matchers instead. Comma-separated list of email addresses or users that should receive email notifications.
            public var mailto: String?
            /// Backup mode.
            public var mode: String?
            /// Only run if executed on this node.
            public var node: String?
            /// Template string for generating notes for the backup(s). It can contain variables which will be replaced by their values. Currently supported are {{cluster}}, {{guestname}}, {{node}}, {{uid}}, and {{vmid}}, but more might be added in the future. Needs to be a single line, newline and backslash need to be escaped as '\n' and '\\' respectively.
            public var notesTemplate: String?
            /// Determine which notification system to use. If set to 'legacy-sendmail', vzdump will consider the mailto/mailnotification parameters and send emails to the specified address(es) via the 'sendmail' command. If set to 'notification-system', a notification will be sent via PVE's notification system, and the mailto and mailnotification will be ignored. If set to 'auto' (default setting), an email will be sent if mailto is set, and the notification system will be used if not. If set to 'none', no notification will be sent.
            public var notificationMode: String?
            /// PBS mode used to detect file changes and switch encoding format for container backups.
            public var pbsChangeDetectionMode: String?
            /// Other performance-related settings.
            public var performance: String?
            /// Use pigz instead of gzip when N>0. N=1 uses half of cores, N>1 uses N as thread count.
            public var pigz: Int?
            /// Backup all known guest systems included in the specified pool.
            public var pool: String?
            /// If true, mark backup(s) as protected.
            public var protected: Bool?
            /// Use these retention options instead of those from the storage configuration.
            public var pruneBackups: String?
            /// Be quiet.
            public var quiet: Bool?
            /// Prune older backups according to 'prune-backups'.
            public var remove: Bool?
            /// Use specified hook script.
            public var script: String?
            /// Exclude temporary files and logs.
            public var stdexcludes: Bool?
            /// Stop running backup jobs on this host.
            public var stop: Bool?
            /// Maximal time to wait until a guest system is stopped (minutes).
            public var stopwait: Int?
            /// Store resulting file to this storage.
            public var storage: String?
            /// Store temporary files to specified directory.
            public var tmpdir: String?
            /// The ID of the guest system you want to backup.
            public var vmid: String?
            /// Zstd threads. N=0 uses half of the available cores, if N is set to a value bigger than 0, N is used as thread count.
            public var zstd: Int?

            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                all = c.flexibleBool(AnyCodingKey("all"))
                bwlimit = c.flexibleInt(AnyCodingKey("bwlimit"))
                compress = c.flexibleString(AnyCodingKey("compress"))
                dumpdir = c.flexibleString(AnyCodingKey("dumpdir"))
                exclude = c.flexibleString(AnyCodingKey("exclude"))
                excludePath = c.lenientArray(String.self, forKey: AnyCodingKey("exclude-path"))
                fleecing = c.flexibleString(AnyCodingKey("fleecing"))
                ionice = c.flexibleInt(AnyCodingKey("ionice"))
                lockwait = c.flexibleInt(AnyCodingKey("lockwait"))
                mailnotification = c.flexibleString(AnyCodingKey("mailnotification"))
                mailto = c.flexibleString(AnyCodingKey("mailto"))
                mode = c.flexibleString(AnyCodingKey("mode"))
                node = c.flexibleString(AnyCodingKey("node"))
                notesTemplate = c.flexibleString(AnyCodingKey("notes-template"))
                notificationMode = c.flexibleString(AnyCodingKey("notification-mode"))
                pbsChangeDetectionMode = c.flexibleString(AnyCodingKey("pbs-change-detection-mode"))
                performance = c.flexibleString(AnyCodingKey("performance"))
                pigz = c.flexibleInt(AnyCodingKey("pigz"))
                pool = c.flexibleString(AnyCodingKey("pool"))
                protected = c.flexibleBool(AnyCodingKey("protected"))
                pruneBackups = c.flexibleString(AnyCodingKey("prune-backups"))
                quiet = c.flexibleBool(AnyCodingKey("quiet"))
                remove = c.flexibleBool(AnyCodingKey("remove"))
                script = c.flexibleString(AnyCodingKey("script"))
                stdexcludes = c.flexibleBool(AnyCodingKey("stdexcludes"))
                stop = c.flexibleBool(AnyCodingKey("stop"))
                stopwait = c.flexibleInt(AnyCodingKey("stopwait"))
                storage = c.flexibleString(AnyCodingKey("storage"))
                tmpdir = c.flexibleString(AnyCodingKey("tmpdir"))
                vmid = c.flexibleString(AnyCodingKey("vmid"))
                zstd = c.flexibleInt(AnyCodingKey("zstd"))
            }
        }
    }

